toolArgs.file_text:
@page "/settings"
@namespace sv_e2b0161cbd3943b5a95b3fa09fe75a9c.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

::deep .settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

::deep .sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border: none;
    background: none;
    cursor: pointer;
    font-size: 0.95rem;
    color: #555;
    text-align: left;
    width: 100%;
    transition: background 0.15s, color 0.15s;
}

::deep .sidebar-item:hover {
    background: #e9ecef;
    color: #333;
}

::deep .sidebar-item.active {
    background: #0d6efd;
    color: #fff;
    font-weight: 600;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

::deep .settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
}

::deep .form-group {
    margin-bottom: 1.25rem;
}

::deep .form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
    color: #333;
}

::deep .form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.95rem;
}

::deep .form-control:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

::deep .form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

::deep .btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    font-weight: 500;
    transition: background 0.15s;
}

::deep .btn-primary {
    background: #0d6efd;
    color: #fff;
}

::deep .btn-primary:hover {
    background: #0b5ed7;
}

::deep .btn-secondary {
    background: #6c757d;
    color: #fff;
}

::deep .btn-secondary:hover {
    background: #5c636a;
}

::deep .btn-danger {
    background: #dc3545;
    color: #fff;
}

::deep .btn-danger:hover {
    background: #bb2d3b;
}

::deep .btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

::deep .toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    animation: fadeIn 0.3s ease;
}

::deep .toast.success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

::deep .toast.error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

/* Avatar */
::deep .avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

::deep .avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e0e0e0;
}

::deep .avatar-url {
    font-size: 0.8rem;
    color: #6c757d;
    word-break: break-all;
}

/* Toggle items */
::deep .toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
}

::deep .toggle-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

::deep .toggle-item input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
    accent-color: #0d6efd;
}

::deep .channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
    padding-left: 0.5rem;
}

/* Security */
::deep .expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

::deep .panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.85rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

::deep .panel-header:hover {
    background: #e9ecef;
}

::deep .panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

::deep .security-item {
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #f0f0f0;
}

::deep .status-row {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

::deep .status-indicator {
    font-weight: 500;
}

::deep .status-indicator.enabled {
    color: #198754;
}

::deep .status-indicator.disabled {
    color: #6c757d;
}

::deep .info-text {
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.5rem;
}

::deep .sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

::deep .sessions-table th,
::deep .sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

::deep .sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
}

::deep .current-badge {
    font-size: 0.8rem;
    color: #198754;
    font-weight: 500;
}

/* Dialog */
::deep .dialog-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

::deep .dialog {
    background: #fff;
    border-radius: 8px;
    padding: 1.5rem;
    min-width: 360px;
    max-width: 480px;
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
}

::deep .dialog h4 {
    margin-bottom: 0.75rem;
}

::deep .dialog-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
    justify-content: flex-end;
}

/* Appearance preview */
::deep .radio-group {
    display: flex;
    gap: 1.25rem;
}

::deep .radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

::deep .appearance-preview {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    transition: all 0.3s ease;
}

::deep .appearance-preview h4 {
    margin-bottom: 0.75rem;
}

::deep .preview-card {
    margin-top: 1rem;
    padding: 1rem;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
}

::deep .preview-theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

::deep .preview-theme-dark .preview-card {
    background: #2d2d2d;
    border-color: #555;
}

::deep .preview-theme-light {
    background: #ffffff;
    color: #333;
}

::deep .preview-theme-system {
    background: #f0f4f8;
    color: #333;
}

::deep .preview-font-small {
    font-size: 0.8rem;
}

::deep .preview-font-medium {
    font-size: 1rem;
}

::deep .preview-font-large {
    font-size: 1.2rem;
}

::deep .preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

::deep .preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

